/* Raider PhysLab: free-response practice (AP Physics 1, Units 1 and 2), merged into each tool by BioLab.addFRQ.
   Format and rules: ENGINE.md, "Free-response practice". Every number here is recomputed by a script (frq_numbers.py in the build notes).
   Point totals follow the AP Physics 1 exam from 2025: Mathematical routines 10, Translation between representations 12,
   Experimental design and analysis 10, Qualitative/quantitative translation 8. Each scoring-guide line is 1 point.
   "verify" is read only by the test script, to check numbers against the simulation's own model. */
(function(){
'use strict';
/* small helpers for the figures and data tables (theme-aware classes in biolab.css: .fq-fig, .fq-data) */
const fig=(w,h,label,body,cap)=>`<figure class="fq-fig"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}">${body}</svg>${cap?`<figcaption>${cap}</figcaption>`:''}</figure>`;
const HEAD={ac:'acf',ln:'hf',lt:'mf'};
const A=(x1,y1,x2,y2,c)=>{c=c||'ac';const L=Math.hypot(x2-x1,y2-y1),ux=(x2-x1)/L,uy=(y2-y1)/L,h=11,w=5.5,bx=x2-ux*h,by=y2-uy*h,f=n=>n.toFixed(1);
  return `<line class="${c}" x1="${f(x1)}" y1="${f(y1)}" x2="${f(bx)}" y2="${f(by)}"/><polygon class="${HEAD[c]}" points="${f(x2)},${f(y2)} ${f(bx-uy*w)},${f(by+ux*w)} ${f(bx+uy*w)},${f(by-ux*w)}"/>`;};
const T=(x,y,s,o)=>{o=o||{};return `<text class="${o.c||'tx'}" x="${x}" y="${y}"${o.a?` text-anchor="${o.a}"`:''}>${s}</text>`;};
const L=(x1,y1,x2,y2,c)=>`<line class="${c||'ln'}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`;
const R=(x,y,w,h,c)=>`<rect class="${c||'sf'}" x="${x}" y="${y}" width="${w}" height="${h}" rx="3"/>`;
const C=(x,y,r,c)=>`<circle class="${c||'sf'}" cx="${x}" cy="${y}" r="${r}"/>`;
const P=(pts,c)=>`<polyline class="${c||'dash'}" points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}"/>`;
const dim=(x1,y1,x2,y2,s,tx,ty,a)=>`${A((x1+x2)/2,(y1+y2)/2,x1,y1,'lt')}${A((x1+x2)/2,(y1+y2)/2,x2,y2,'lt')}${T(tx,ty,s,{c:'tm',a})}`;
const tbl=(cap,head,rows)=>`<div class="fq-tw"><table class="fq-data"><caption>${cap}</caption><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;

/* ---- figures ---- */
const figCart=fig(460,150,'A cart on a level track at x = 2.0 m, moving right at 3.0 m/s, with an acceleration of 1.5 m/s² to the left',
  L(20,112,445,112)+[0,1,2,3,4,5,6].map(x=>L(40+60*x,107,40+60*x,117,'lt')+T(40+60*x,136,String(x),{c:'tm',a:'middle'})).join('')+T(445,100,'x (m)',{c:'tm',a:'end'})+
  R(138,80,44,24)+C(148,106,5)+C(172,106,5)+R(141,70,14,10)+T(127,78,'fan',{c:'tm',a:'end'})+
  A(160,56,236,56,'ln')+T(242,61,'v₀ = 3.0 m/s')+A(160,32,110,32,'ac')+T(102,37,'a = 1.5 m/s²',{a:'end'}),
  'Positive is to the right. The cart is shown at t = 0.');
const figBalcony=fig(460,220,'A ball thrown straight up at 8.0 m/s from a balcony 15 m above the ground',
  R(40,40,90,166,'sf')+L(130,62,190,62)+C(160,52,7)+A(160,42,160,6,'ac')+T(172,22,'8.0 m/s')+R(0,206,460,14,'gnd')+L(0,206,460,206)+
  dim(232,62,232,206,'15 m',242,140),'Up is positive.');
const figRiver=(()=>{const top=34,bot=176;return fig(460,215,'A river of width D. A kayak points straight across at speed v sub k while the water flows to the right at v sub w. It lands a distance x downstream.',
  R(0,0,460,top,'gnd')+R(0,bot,460,215-bot,'gnd')+L(0,top,460,top)+L(0,bot,460,bot)+
  A(350,96,420,96,'lt')+A(350,140,420,140,'lt')+T(350,80,'water, v<tspan baseline-shift="sub">w</tspan>',{c:'tm'})+
  P([[120,bot],[300,top]])+A(120,bot,120,112,'ac')+T(112,130,'v<tspan baseline-shift="sub">k</tspan>',{a:'end'})+C(120,bot,4,'sf')+
  dim(40,top,40,bot,'D',50,110)+L(120,top-8,120,top,'lt')+dim(120,top-14,300,top-14,'x',210,top-20,'middle'),'Seen from above. The dashed line is her path relative to the shore.');})();
const figWall=(()=>{const s=12,x0=100,y0=185,H=4,v=15,th=40*Math.PI/180,g=9.8,vx=v*Math.cos(th),vy=v*Math.sin(th),tf=(vy+Math.sqrt(vy*vy+2*g*H))/g,pts=[];
  for(let i=0;i<=40;i++){const t=tf*i/40;pts.push([x0+s*vx*t,y0-s*(H+vy*t-g*t*t/2)]);}
  return fig(460,215,'A water balloon launched at 15 m/s and 40° above the horizontal from the top of a 4.0 m wall',
    R(x0-34,y0-s*H,34,s*H,'sf')+R(0,y0,460,30,'gnd')+L(0,y0,460,y0)+P(pts)+A(x0,y0-s*H,x0+70*Math.cos(th),y0-s*H-70*Math.sin(th),'ac')+
    T(x0+40,y0-s*H-56,'15 m/s',{a:'end'})+L(x0,y0-s*H,x0+60,y0-s*H,'lt')+`<path class="lt" d="M ${x0+34} ${y0-s*H} A 34 34 0 0 0 ${(x0+34*Math.cos(th)).toFixed(1)} ${(y0-s*H-34*Math.sin(th)).toFixed(1)}"/>`+T(x0+40,y0-s*H-6,'40°',{c:'tm'})+
    dim(x0-44,y0-s*H,x0-44,y0,'4.0 m',x0-50,y0-20,'end'),'Not to scale with the ground distance. The dashed curve is the path.');})();
const figCrate=fig(460,160,'A student pushes a 40 kg crate to the right with a 200 N horizontal force on a level wooden floor',
  R(0,128,460,32,'gnd')+L(0,128,460,128)+R(200,64,90,64)+T(245,102,'40 kg',{a:'middle'})+A(110,96,198,96,'ac')+T(104,54,'push, 200 N')+
  C(78,62,10)+L(78,72,78,106)+L(78,82,108,96)+L(78,106,66,128)+L(78,106,92,128),'Wooden floor: μ<sub>s</sub> = 0.40, μ<sub>k</sub> = 0.30.');
const figScale=fig(460,150,'A 0.50 kg wooden block on a felt table, pulled to the right by a string attached to a spring scale',
  R(0,104,460,46,'gnd')+L(0,104,460,104)+R(90,62,80,42)+T(130,89,'block',{a:'middle'})+L(170,83,262,83)+R(262,72,92,22)+
  [0,1,2,3,4,5].map(k=>L(272+14*k,72,272+14*k,80,'lt')).join('')+L(354,83,384,83)+A(388,83,440,83,'ac')+T(406,70,'pull',{a:'middle'})+T(308,62,'spring scale',{c:'tm',a:'middle'}),
  'The string and scale are level with the table.');
const figRamp=(()=>{const th=30*Math.PI/180,x0=40,y0=190,Lr=360,xt=x0+Lr*Math.cos(th),yt=y0-Lr*Math.sin(th),u=[Math.cos(th),-Math.sin(th)],n=[-Math.sin(th),-Math.cos(th)],bx=x0+0.55*Lr*u[0],by=y0+0.55*Lr*u[1],
  c=(a,b)=>[bx+a*u[0]+b*n[0],by+a*u[1]+b*n[1]],q=[c(-34,0),c(34,0),c(34,36),c(-34,36)];
  return fig(460,215,'A 5.0 kg block on a wooden ramp tilted 30° above the horizontal',
    `<polygon class="gnd" points="${x0},${y0} ${xt.toFixed(1)},${y0} ${xt.toFixed(1)},${yt.toFixed(1)}"/>`+L(x0,y0,xt,yt)+L(x0,y0,xt,y0)+
    `<polygon class="sf" points="${q.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}"/>`+T(c(-6,58)[0].toFixed(1),(c(-6,58)[1]+5).toFixed(1),'5.0 kg',{a:'middle'})+
    `<path class="lt" d="M ${x0+60} ${y0} A 60 60 0 0 0 ${(x0+60*Math.cos(th)).toFixed(1)} ${(y0-60*Math.sin(th)).toFixed(1)}"/>`+T(x0+68,y0-10,'30°',{c:'tm'}),
    'Wood on wood: μ<sub>s</sub> = 0.45, μ<sub>k</sub> = 0.30.');})();
const figTable=fig(460,230,'Block 1 on a level table, tied by a string over a pulley at the edge to Block 2, which hangs below',
  R(20,92,300,14,'gnd')+L(20,92,320,92)+L(60,106,60,226,'lt')+L(270,106,270,226,'lt')+R(110,52,80,40)+T(150,77,'Block 1',{a:'middle'})+
  L(190,72,322,72)+C(334,84,13)+L(347,84,347,150)+R(320,150,54,44)+T(347,177,'2',{a:'middle'})+T(150,42,'m<tspan baseline-shift="sub">1</tspan> = 2.0 kg',{c:'tm',a:'middle'})+T(347,218,'m<tspan baseline-shift="sub">2</tspan> = 1.0 kg',{c:'tm',a:'middle'}),
  'Friction between Block 1 and the table: μ<sub>k</sub> = 0.20.');
const figAtwood=fig(460,230,'An Atwood machine: two masses hanging from a string over a pulley that hangs from the ceiling',
  R(0,0,460,12,'gnd')+L(0,12,460,12)+L(230,12,230,38)+C(230,50,24)+C(230,50,3,'ln')+L(206,50,206,92)+L(254,50,254,150)+
  R(184,92,44,40)+T(206,117,'m₁',{a:'middle'})+R(232,150,44,46)+T(254,178,'m₂',{a:'middle'})+A(300,150,300,206,'ac')+T(308,184,'falls a distance d',{c:'tm'}),
  'The total mass m<sub>1</sub> + m<sub>2</sub> stays 2.0 kg in every run.');
const figCurve=fig(460,210,'Seen from above: a car on a flat curve of radius 50 m. The center of the curve is below the car.',
  `<path class="road" d="M 70 190 A 170 170 0 0 1 390 190"/>`+`<path class="lt" d="M 70 190 A 170 170 0 0 1 390 190"/>`+C(230,190,4,'ln')+T(238,205,'center',{c:'tm'})+
  `<line class="dash" x1="230" y1="190" x2="230" y2="28"/>`+T(238,120,'r = 50 m',{c:'tm'})+R(212,10,36,22)+A(256,21,320,21,'ln')+T(326,26,'v'),
  'The car moves at constant speed along the curve.');
const figOrbit=fig(460,220,'Earth with two satellites, A and B, on the same circular orbit of radius r. Satellite B has twice the mass of A.',
  C(230,110,42)+T(230,100,'Earth',{a:'middle'})+`<circle class="dash" cx="230" cy="110" r="92"/>`+C(230,18,6)+T(244,12,'A, mass m')+C(322,110,9)+T(336,115,'B, mass 2m')+
  L(230,110,165,175,'lt')+T(178,156,'r',{c:'tm'}),'Not to scale.');

BioLab.addFRQ({
/* ===================== Unit 1: Kinematics ===================== */
motion1d:[{id:'motion1d-1',kind:'ap',type:'Translation between representations',title:'A fan cart that turns around',minutes:27,
  stem:`<p>A cart sits on a long, level track. A fan mounted on the cart pushes it with a constant force toward the left. Take the positive direction to be to the right.</p><p>At time t = 0, the cart is at position x = 2.0 m and is moving to the right at 3.0 m/s. The fan gives the cart a constant acceleration of 1.5 m/s² to the left. Friction is negligible.</p>${figCart}`,
  parts:[
  {label:'a',kind:'sketch',pts:2,q:'On a set of axes, sketch a graph of the cart’s velocity v as a function of time t from t = 0 to t = 4.0 s. Label the velocity at t = 0 and the time when v = 0.',
    guide:['For a straight line with a negative slope that starts at +3.0 m/s','For a line that crosses v = 0 at t = 2.0 s and continues below the axis (to −3.0 m/s at t = 4.0 s)'],
    model:'<p>A straight line from (0 s, +3.0 m/s) down to (4.0 s, −3.0 m/s). It crosses zero at t = 3.0 ÷ 1.5 = 2.0 s. The slope is −1.5 m/s² everywhere.</p>',
    mistakes:['Stopping the line at v = 0. The fan keeps pushing left after the cart stops, so the cart speeds up to the left and v becomes negative.','Drawing the speed (a V shape) instead of the velocity. Velocity has a sign, so the graph goes below the axis.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the cart’s greatest position x<sub>max</sub> in terms of the starting position x<sub>0</sub>, the starting speed v<sub>0</sub>, the magnitude a of the acceleration, and physical constants as appropriate. Begin your derivation by writing a fundamental equation of kinematics.',
    guide:['For starting with a kinematics equation that relates velocity, acceleration and displacement, for example v<sub>x</sub>² = v<sub>x0</sub>² + 2a<sub>x</sub>(x − x<sub>0</sub>)','For using v<sub>x</sub> = 0 at the greatest position and a<sub>x</sub> = −a, a negative acceleration because it points left','For x<sub>max</sub> = x<sub>0</sub> + v<sub>0</sub>²/(2a)'],
    model:'<p>v<sub>x</sub>² = v<sub>x0</sub>² + 2a<sub>x</sub>(x − x<sub>0</sub>). At the greatest position the cart stops for an instant, so v<sub>x</sub> = 0. The acceleration points left, so a<sub>x</sub> = −a.</p><p>0 = v<sub>0</sub>² − 2a(x<sub>max</sub> − x<sub>0</sub>), so <b>x<sub>max</sub> = x<sub>0</sub> + v<sub>0</sub>²/(2a)</b>.</p>',
    mistakes:['Sign error: using +a. That gives x<sub>max</sub> = x<sub>0</sub> − v<sub>0</sub>²/(2a), a point behind the start, which makes no sense for a cart moving right.','Writing only the final expression. On a “derive” question, readers look for the starting equation and the step where you set v = 0.']},
  {label:'c',kind:'calc',pts:2,q:'Calculate the value of x<sub>max</sub>.',num:{ans:5.0,tol:0.1,unit:'m'},
    guide:['For substituting x<sub>0</sub> = 2.0 m, v<sub>0</sub> = 3.0 m/s and a = 1.5 m/s² into an expression consistent with part (b)','For x<sub>max</sub> = 5.0 m, with units'],
    model:'<p>x<sub>max</sub> = 2.0 m + (3.0 m/s)² ÷ (2 × 1.5 m/s²) = 2.0 m + 3.0 m = <b>5.0 m</b>.</p>',
    mistakes:['Forgetting to add x<sub>0</sub>. The cart travels 3.0 m from where it started, so its position is 5.0 m.']},
  {label:'d',kind:'sketch',pts:3,q:'On a separate set of axes, sketch the cart’s position x as a function of time from t = 0 to t = 4.0 s. Your graph should be consistent with your velocity graph in part (a).',
    guide:['For a curve that is concave down for the whole interval','For a maximum of 5.0 m at t = 2.0 s, the same time v = 0 on your velocity graph','For a curve that is symmetric about t = 2.0 s and returns to x = 2.0 m at t = 4.0 s'],
    model:'<p>A downward-opening parabola. It starts at 2.0 m with a positive slope, levels off to a rounded top at (2.0 s, 5.0 m), and comes back down to 2.0 m at 4.0 s. The slope of this graph at each instant is the velocity from part (a): steep and positive, then zero at the top, then steep and negative.</p>',
    mistakes:['Drawing two straight lines that meet in a sharp peak. A sharp corner would mean the velocity jumped from +3.0 to −3.0 m/s in an instant. The velocity changes smoothly, so the top is rounded.','Putting the peak at a different time than the zero crossing in part (a). The graphs must agree: the top of the x graph is where v = 0.']},
  {label:'e',kind:'explain',pts:2,q:'A student says, “At t = 2.0 s the cart is not moving, so its acceleration at that instant is zero.” Do you agree or disagree? Justify your answer using your graph from part (a).',
    guide:['For disagreeing, and stating that the acceleration at t = 2.0 s is still 1.5 m/s² to the left','For a justification that uses the slope of the velocity-time graph: the slope at t = 2.0 s is the same constant, nonzero value as at every other time'],
    model:'<p>Disagree. Acceleration is the slope of the velocity-time graph, not the value of v. At t = 2.0 s the graph crosses zero, but its slope is still −1.5 m/s², the same as everywhere else on the straight line. So the cart is accelerating at 1.5 m/s² to the left at that instant, which is why it starts moving left right after.</p>',
    mistakes:['Agreeing because “v = 0 means a = 0.” Velocity can be zero while it is changing. If a were zero at t = 2.0 s, the cart would stay stopped.','Giving a claim with no reason. “Disagree” alone earns only the first point. Point to the slope of the graph to earn the second.']}
  ],
  lab:{set:{mode:'explore',x0:2,v0:3,a:-1.5,strobe:true},look:'The cart starts at x = 2.0 m moving right at 3.0 m/s, with a = −1.5 m/s². Watch <b>Velocity</b> reach zero and read <b>Position</b> at that moment. Then watch the cart come back past 2.0 m.'},
  verify:[{set:{mode:'explore',x0:2,v0:3,a:-1.5},run:2.0,m:'x',v:5.0,tol:0.04},{set:{mode:'explore',x0:2,v0:3,a:-1.5},run:2.0,m:'v',v:0,tol:0.02},{set:{mode:'explore',x0:2,v0:3,a:-1.5},run:4.0,m:'x',v:2.0,tol:0.04}]}],

freefall:[{id:'freefall-1',kind:'ap',type:'Mathematical routines',title:'A ball thrown up from a balcony',minutes:22,
  stem:`<p>A student stands on a balcony and throws a ball straight up. The ball leaves her hand 15 m above the ground, moving upward at 8.0 m/s. It rises, falls back past the balcony and lands on the ground below. Air resistance is negligible. Take up as positive and use g = 9.8 m/s².</p>${figBalcony}`,
  parts:[
  {label:'a',kind:'explain',pts:3,q:'Derive an expression for the speed v of the ball just before it hits the ground, in terms of v<sub>0</sub>, h, and physical constants as appropriate. Here v<sub>0</sub> is the launch speed and h is the height of the launch point above the ground. Begin your derivation by writing a fundamental equation of kinematics.',
    guide:['For starting with a kinematics equation that relates velocity, acceleration and displacement, for example v<sub>y</sub>² = v<sub>y0</sub>² + 2a<sub>y</sub>Δy','For substituting a<sub>y</sub> = −g and Δy = −h, with signs consistent with up as positive','For v = √(v<sub>0</sub>² + 2gh)'],
    model:'<p>v<sub>y</sub>² = v<sub>y0</sub>² + 2a<sub>y</sub>Δy. With up as positive, v<sub>y0</sub> = +v<sub>0</sub>, a<sub>y</sub> = −g, and the ball ends a distance h below where it started, so Δy = −h.</p><p>v<sub>y</sub>² = v<sub>0</sub>² + 2(−g)(−h) = v<sub>0</sub>² + 2gh, so <b>v = √(v<sub>0</sub>² + 2gh)</b>.</p>',
    mistakes:['Sign error: writing Δy = +h, which gives v<sub>0</sub>² − 2gh. A ball thrown up and landing below its start must hit the ground faster than it left, so the two terms add.','Using y = y<sub>0</sub> + v<sub>0</sub>t + ½a<sub>y</sub>t². It works, but it brings in t, which the question does not give you. Pick the equation without time.']},
  {label:'b',kind:'calc',pts:1,q:'Calculate the speed of the ball just before it hits the ground.',num:{ans:18.9,tol:0.3,unit:'m/s'},
    guide:['For a speed of about 19 m/s (18.9 m/s), with substitution into an expression consistent with part (a)'],
    model:'<p>v = √(8.0² + 2 × 9.8 × 15) = √(64 + 294) = √358 = <b>18.9 m/s</b>.</p>',
    mistakes:['Getting √(64 − 294), which has no real value. That comes from the sign error in part (a).']},
  {label:'c',kind:'calc',pts:2,q:'Calculate the time the ball is in the air, from leaving her hand to hitting the ground.',num:{ans:2.75,tol:0.05,unit:'s'},
    guide:['For a correct method with consistent signs, for example v<sub>y</sub> = v<sub>y0</sub> + a<sub>y</sub>t with v<sub>y</sub> = −18.9 m/s, or 0 = 15 + 8.0t − 4.9t²','For t ≈ 2.7 s (2.75 s), choosing the positive root if you used the quadratic'],
    model:'<p>The ball lands moving down, so v<sub>y</sub> = −18.9 m/s. From v<sub>y</sub> = v<sub>y0</sub> + a<sub>y</sub>t: −18.9 = 8.0 − 9.8t, so t = (8.0 + 18.9) ÷ 9.8 = <b>2.75 s</b>. The quadratic 0 = 15 + 8.0t − 4.9t² gives the same answer; its other root, −1.11 s, is before the throw.</p>',
    mistakes:['Using +18.9 m/s for the final velocity. The ball is moving down when it lands, so its velocity is negative.','Using t = √(2h/g) = 1.75 s. That formula is only for an object dropped from rest.']},
  {label:'d',kind:'sketch',pts:2,q:'Sketch a graph of the ball’s vertical velocity v<sub>y</sub> as a function of time for the whole flight. Label the velocity at the start and at the end.',
    guide:['For a single straight line with a negative slope (slope −9.8 m/s²) that starts at +8.0 m/s','For a line that crosses zero at about 0.8 s and ends at about −19 m/s at the landing time, with no break, bend or flat section at the top'],
    model:'<p>One straight line from (0, +8.0 m/s) to (2.75 s, −18.9 m/s). It crosses v<sub>y</sub> = 0 at t = 8.0 ÷ 9.8 = 0.82 s, the top of the flight. The slope is −9.8 m/s² the whole time.</p>',
    mistakes:['Drawing a flat spot at the top, as if gravity pauses there. The acceleration is −9.8 m/s² at every instant, including the top.','Drawing a V shape that bounces off the axis. That is a speed graph. Velocity becomes negative on the way down.']},
  {label:'e',kind:'explain',pts:2,q:'A second ball is thrown straight down from the same point at 8.0 m/s. Is its speed just before it hits the ground greater than, less than, or equal to the speed of the first ball? Justify your answer using your expression from part (a).',
    guide:['For stating that the speeds are equal','For a justification that refers to part (a): the expression depends on v<sub>0</sub>², which is the same whether the ball is thrown up or down, and on h and g, which are also the same (or: the first ball passes the balcony moving down at 8.0 m/s)'],
    model:'<p>Equal. In v = √(v<sub>0</sub>² + 2gh), the launch velocity appears only as v<sub>0</sub>², so +8.0 m/s and −8.0 m/s give the same result, and h and g are the same for both balls. Physically, the first ball comes back past the balcony moving down at 8.0 m/s, so from there its motion matches the second ball’s. Both land at 18.9 m/s. The second ball just gets there 1.63 s sooner, the time the first ball spends going up and back.</p>',
    mistakes:['Saying the thrown-down ball is faster because it was thrown toward the ground. It gets there sooner, not faster.','Writing “equal” with no reason. The claim and the justification are separate points.']}
  ],
  lab:{set:{h:15,v0:8,air:false,planet:'earth',bounce:false},act:'again',look:'Ball A is thrown up at 8.0 m/s from 15 m. Read <b>A hit the ground at</b>, and at Closer look, <b>A impact speed</b>. Then set <b>Launch velocity</b> to −8 m/s, press <b>Drop again</b> and compare.'},
  verify:[{set:{h:15,v0:8,air:false,planet:'earth',bounce:false},act:'again',run:3.2,m:'landA',v:2.75,tol:0.02},{set:{h:15,v0:8,air:false,planet:'earth',bounce:false},act:'again',run:3.2,m:'impA',v:18.9,tol:0.1},{set:{h:15,v0:-8,air:false,planet:'earth',bounce:false},act:'again',run:2.0,m:'landA',v:1.11,tol:0.02},{set:{h:15,v0:-8,air:false,planet:'earth',bounce:false},act:'again',run:2.0,m:'impA',v:18.9,tol:0.1}]}],

vectors2d:[{id:'vectors2d-1',kind:'ap',type:'Qualitative/quantitative translation',title:'Paddling across a river',minutes:20,
  stem:`<p>A kayaker paddles across a straight river of width D. She always points the kayak straight across the river, perpendicular to the banks, and paddles at a constant speed v<sub>k</sub> relative to the water. The water moves parallel to the banks at a constant speed v<sub>w</sub>. She lands a distance x downstream from the point directly across from where she started.</p>${figRiver}`,
  parts:[
  {label:'a',kind:'explain',pts:3,q:'In the spring, the river flows twice as fast. The kayaker paddles at the same speed and points straight across again. Without using equations, explain how (i) the time to cross and (ii) the distance x change compared with before.',
    guide:['For indicating that the time to cross stays the same and the distance x increases','For justifying the time: the current is parallel to the banks, so it adds no velocity across the river, and only v<sub>k</sub> carries her across the width D','For justifying the distance: she is carried downstream for the same time at twice the downstream speed, so she drifts farther (twice as far)'],
    model:'<p>(i) The time stays the same. The water carries her along the river, not across it, so the only velocity across the river is her paddling speed relative to the water, and that has not changed. She still has to cover the same width at the same speed across.</p><p>(ii) The distance x increases. For that same time, she is carried downstream at twice the speed, so she drifts twice as far.</p>',
    mistakes:['Saying the trip takes longer because the kayak’s path is longer. The path is longer, but her speed relative to the shore is also larger. Only the part of her velocity across the river sets the time.','Adding the speeds as plain numbers. Her velocity relative to the shore is the vector sum of two perpendicular velocities.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for x in terms of D, v<sub>k</sub>, v<sub>w</sub>, and physical constants as appropriate.',
    guide:['For treating the motion across the river and the motion along it separately, with the time to cross t = D/v<sub>k</sub>','For x = v<sub>w</sub>t, using the same time for the motion along the river','For x = v<sub>w</sub>D/v<sub>k</sub>'],
    model:'<p>Across the river: the velocity is v<sub>k</sub> and the distance is D, so t = D/v<sub>k</sub>. Along the river: the velocity is v<sub>w</sub> for that same time, so x = v<sub>w</sub>t. Substituting, <b>x = v<sub>w</sub>D/v<sub>k</sub></b>.</p>',
    mistakes:['Dividing the width D by her speed relative to the shore, √(v<sub>k</sub>² + v<sub>w</sub>²). That speed goes with the length of the diagonal path, not with the width.']},
  {label:'c',kind:'explain',pts:2,q:'Explain how your expression from part (b) supports your answers to part (a).',
    guide:['For describing the functional dependence in your expression: x is directly proportional to v<sub>w</sub>, and the time D/v<sub>k</sub> does not depend on v<sub>w</sub>','For connecting this to part (a): doubling v<sub>w</sub> doubles x and leaves the time unchanged, consistent with your claims'],
    model:'<p>In x = v<sub>w</sub>D/v<sub>k</sub>, x is directly proportional to v<sub>w</sub> when D and v<sub>k</sub> stay the same, so doubling the current doubles x. The time t = D/v<sub>k</sub> does not contain v<sub>w</sub> at all, so the crossing time does not change. Both agree with part (a). For example, with D = 40 m and v<sub>k</sub> = 2.0 m/s, the crossing takes 20 s either way, and x goes from 30 m at v<sub>w</sub> = 1.5 m/s to 60 m at 3.0 m/s.</p>',
    mistakes:['Repeating the equation without saying how x depends on v<sub>w</sub>. Use words like “directly proportional to” or “does not depend on.”','Leaving a contradiction between parts (a) and (c). If your expression and your claim disagree, say which one you trust and why.']}
  ],
  lab:{set:{mode:'river',bs:2.0,aim:0,cur:1.5,wid:40},act:'go',look:'The boat aims straight across at 2.0 m/s in a 1.5 m/s current, on a 40 m river. Read <b>Time on the water</b> and <b>Downstream drift</b>. Then set <b>River current</b> to 3.0 m/s, press <b>Start again</b> and compare.'},
  verify:[{set:{mode:'river',bs:2.0,aim:0,cur:1.5,wid:40},act:'go',run:25,m:'crossT',v:20,tol:0.1},{set:{mode:'river',bs:2.0,aim:0,cur:1.5,wid:40},act:'go',run:25,m:'drift',v:30,tol:0.2},{set:{mode:'river',bs:2.0,aim:0,cur:3.0,wid:40},act:'go',run:25,m:'crossT',v:20,tol:0.1},{set:{mode:'river',bs:2.0,aim:0,cur:3.0,wid:40},act:'go',run:25,m:'drift',v:60,tol:0.3}]}],

projectile:[{id:'projectile-1',kind:'ap',type:'Mathematical routines',title:'A water balloon launched from a wall',minutes:22,
  stem:`<p>A water balloon is launched from the top edge of a wall 4.0 m above level ground. It leaves the launcher at 15 m/s, at 40° above the horizontal, and lands on the ground. Air resistance is negligible. Use g = 9.8 m/s².</p>${figWall}`,
  parts:[
  {label:'a',kind:'explain',pts:3,q:'Derive an expression for the maximum height H of the balloon above the ground, in terms of the launch speed v<sub>0</sub>, the launch angle θ, the wall height h, and physical constants as appropriate. Begin your derivation by writing a fundamental equation of kinematics.',
    guide:['For starting with a kinematics equation for the vertical motion that relates velocity, acceleration and displacement, for example v<sub>y</sub>² = v<sub>y0</sub>² + 2a<sub>y</sub>Δy','For substituting v<sub>y</sub> = 0 at the highest point, v<sub>y0</sub> = v<sub>0</sub> sin θ and a<sub>y</sub> = −g','For H = h + v<sub>0</sub>² sin²θ/(2g)'],
    model:'<p>Vertically: v<sub>y</sub>² = v<sub>y0</sub>² + 2a<sub>y</sub>Δy. At the top, v<sub>y</sub> = 0. The vertical part of the launch velocity is v<sub>0</sub> sin θ, and a<sub>y</sub> = −g.</p><p>0 = v<sub>0</sub>² sin²θ − 2gΔy, so the rise above the wall is Δy = v<sub>0</sub>² sin²θ/(2g). Adding the wall: <b>H = h + v<sub>0</sub>² sin²θ/(2g)</b>.</p>',
    mistakes:['Using v<sub>0</sub> instead of v<sub>0</sub> sin θ. Only the vertical part of the velocity decides how high it goes.','Forgetting to add h. The expression gives the rise above the launch point, not the height above the ground.']},
  {label:'b',kind:'calc',pts:1,q:'Calculate the maximum height of the balloon above the ground.',num:{ans:8.74,tol:0.1,unit:'m'},
    guide:['For a maximum height of about 8.7 m (8.74 m), with substitution into an expression consistent with part (a)'],
    model:'<p>H = 4.0 + (15 sin 40°)² ÷ (2 × 9.8) = 4.0 + 9.64² ÷ 19.6 = 4.0 + 4.74 = <b>8.74 m</b>.</p>',
    mistakes:['Leaving the calculator in radian mode. In radians, sin 40 is 0.745, not 0.643, which gives about 10.4 m.']},
  {label:'c',kind:'calc',pts:2,q:'Calculate the horizontal distance from the base of the wall to where the balloon lands.',num:{ans:26.7,tol:0.4,unit:'m'},
    guide:['For finding the time in the air from the vertical motion with a displacement of −4.0 m (t ≈ 2.3 s), and using x = (v<sub>0</sub> cos 40°)t with a constant horizontal velocity','For a distance of about 27 m (26.7 m)'],
    model:'<p>Vertical: −4.0 = 9.64t − 4.9t². The positive root is t = [9.64 + √(9.64² + 4 × 4.9 × 4.0)] ÷ 9.8 = 2.32 s.</p><p>Horizontal: v<sub>x</sub> = 15 cos 40° = 11.49 m/s, and it stays constant, so x = 11.49 × 2.32 = <b>26.7 m</b>.</p>',
    mistakes:['Using the range equation v<sub>0</sub>² sin 2θ / g = 22.6 m. It only works when the balloon lands at the height it was launched from. This one lands 4.0 m lower, so it travels farther.','Sign error: writing the displacement as +4.0 m. The balloon ends below its launch point.']},
  {label:'d',kind:'sketch',pts:2,q:'On one set of axes, sketch the horizontal velocity v<sub>x</sub> and the vertical velocity v<sub>y</sub> of the balloon as functions of time, from launch until it lands. Take up and away from the wall as positive.',
    guide:['For v<sub>x</sub> drawn as a horizontal line at a positive value (11.5 m/s) for the whole flight','For v<sub>y</sub> drawn as a straight line with a negative slope that starts at about +9.6 m/s, crosses zero at about 1.0 s, and ends lower than −9.6 m/s (about −13 m/s)'],
    model:'<p>v<sub>x</sub>: a flat line at +11.5 m/s, because no horizontal force acts. v<sub>y</sub>: a straight line from +9.64 m/s with a slope of −9.8 m/s², crossing zero at t = 9.64 ÷ 9.8 = 0.98 s and ending at −13.1 m/s at t = 2.32 s. It ends lower than −9.64 m/s because the balloon falls 4.0 m below its launch height.</p>',
    mistakes:['Drawing v<sub>x</sub> decreasing. With no air resistance, nothing pushes or pulls horizontally, so v<sub>x</sub> never changes.','Ending v<sub>y</sub> at −9.6 m/s, as if the balloon landed at its launch height.']},
  {label:'e',kind:'explain',pts:2,q:'Is the balloon’s speed just before it lands greater than, less than, or equal to its launch speed of 15 m/s? Justify your answer by referring to the horizontal and vertical components of its velocity.',
    guide:['For stating that the landing speed is greater than 15 m/s','For justifying that the horizontal component is unchanged (no horizontal force) while the vertical component is larger in size at landing, because the balloon ends 4.0 m below its launch point'],
    model:'<p>Greater. The horizontal component is 11.5 m/s at launch and at landing, since no horizontal force acts. The vertical component is 9.64 m/s up at launch. On the way down, the balloon passes its launch height moving 9.64 m/s down, then keeps speeding up for another 4.0 m, so it lands with a vertical component of 13.1 m/s down. Same horizontal part, bigger vertical part: the landing speed, √(11.5² + 13.1²) = 17.4 m/s, is greater than 15 m/s.</p>',
    mistakes:['Saying “equal, because energy is conserved.” Energy is conserved, but the balloon ends lower than it started, so some gravitational energy has become kinetic energy.','Adding the components as plain numbers (11.5 + 13.1). Speed is the size of the velocity vector, so use the Pythagorean theorem.']}
  ],
  lab:{set:{mode:'free',ang:40,v0:15,h0:4,air:false,vecs:true},act:'fire',look:'This is the balloon: 15 m/s at 40° from 4.0 m. Read <b>Max height</b>, <b>Horizontal distance</b> and <b>Time in the air</b> when it lands. At Closer look, watch the v<sub>x</sub> and v<sub>y</sub> readouts as it flies.'},
  verify:[{set:{mode:'free',ang:40,v0:15,h0:4,air:false},act:'fire',run:3,m:'maxh',v:8.74,tol:0.03},{set:{mode:'free',ang:40,v0:15,h0:4,air:false},act:'fire',run:3,m:'dist',v:26.7,tol:0.1},{set:{mode:'free',ang:40,v0:15,h0:4,air:false},act:'fire',run:3,m:'tof',v:2.32,tol:0.02}]}],

linearize:[{id:'linearize-1',kind:'ap',type:'Experimental design and analysis',title:'Measuring g with a dropped ball',minutes:25,
  stem:'<p>A group wants to find the acceleration due to gravity, g, by dropping a small steel ball from rest. They have a meterstick, a stand that can hold the ball at different heights, and a timer that starts when the ball is released and stops when the ball reaches a sensor on the floor. Air resistance is negligible.</p>',
  parts:[
  {label:'a',kind:'explain',pts:2,q:'Describe a procedure the group could use to collect data for finding g. Include what they measure, how they measure it, and one thing they could do to reduce experimental uncertainty.',
    guide:['For a procedure that measures the drop height h with the meterstick and the fall time t with the timer, for several different heights','For a way to reduce uncertainty, for example repeating the drop several times at each height and averaging, or using a wide range of heights'],
    model:'<p>Hold the ball at rest at a height h above the floor sensor and measure h with the meterstick, from the bottom of the ball to the sensor. Release it and record the fall time t from the timer. Repeat for at least five heights between about 0.4 m and 1.2 m. At each height, drop the ball three times and average the times, so one bad release does not throw off the data.</p>',
    mistakes:['Measuring only one height. You need several heights to make a graph and find g from a slope.','Writing “be careful” or “do it again” without saying what is repeated or averaged. Name the specific action.']},
  {label:'b',kind:'explain',pts:2,q:'The group wants a graph that is a straight line and whose slope can be used to find g. Identify the quantities they should graph on each axis, and explain how they can find g from the slope.',
    guide:['For quantities that give a linear graph, for example h on the vertical axis and t² on the horizontal axis (or t² against h, or √h against t)','For a correct relationship between the slope and g that matches the chosen axes, for example slope = g/2 for h against t², so g = 2 × slope'],
    model:'<p>From rest, h = ½gt². Graph h on the vertical axis against t² on the horizontal axis. That is a straight line through the origin with slope g/2, so <b>g = 2 × slope</b>. Graphing t² against h also works: then the slope is 2/g, and g = 2 ÷ slope.</p>',
    mistakes:['Wrong axes: graphing h against t. The data curve, so a straight best-fit line through them has a slope that means nothing. Square the time first.','Wrong axes: graphing h against 1/t, or t against h². Check by putting your choice into h = ½gt². Only a pair like h and t² makes a straight line.']},
  {label:'c',kind:'sketch',pts:4,q:`<p>The group records these average times.</p>${tbl('Average fall times',['Drop height h (m)','Fall time t (s)'],[['0.40','0.288'],['0.60','0.348'],['0.80','0.406'],['1.00','0.450'],['1.20','0.497']])}<p>On a grid, plot the data in a way that gives a straight line, using the quantities you chose in part (b). Label the axes with quantities and units, use a linear scale, and draw a best-fit line.</p>`,
    guide:['For plotting a quantity, such as t², that produces a linear graph, consistent with part (b)','For labeling both axes with quantities and units, on linear scales','For plotting the data points correctly','For drawing a single straight best-fit line that follows the trend of the points, not one that connects the dots'],
    model:'<p>Values of t²: 0.0829, 0.121, 0.165, 0.203 and 0.247 s². With h (m) on the vertical axis from 0 to 1.2 m and t² (s²) on the horizontal axis from 0 to 0.25 s², the five points fall close to a straight line through the origin. The best-fit line passes near (0, 0) and (0.25 s², 1.22 m).</p>',
    mistakes:['Labels without units, or units without the quantity (for example “s²” alone). Each axis needs both.','Connecting the dots point to point. Draw one straight line that best fits all the points.','Plotting t instead of t². If your points curve, go back to part (b).']},
  {label:'d',kind:'calc',pts:2,q:'Use your best-fit line to calculate a value for g.',num:{ans:9.8,tol:0.4,unit:'m/s²'},
    guide:['For calculating the slope from two points on the best-fit line (not two data points), and using the relationship from part (b)','For a value of g between 9.4 and 10.2 m/s²'],
    model:'<p>Two points on the line: (0, 0) and (0.25 s², 1.22 m). Slope = 1.22 m ÷ 0.25 s² = 4.88 m/s². Since the slope is g/2, <b>g = 2 × 4.88 = 9.76 m/s²</b>, close to 9.8 m/s².</p>',
    mistakes:['Using one data point, for example g = 2h/t² for the top row. That ignores the other four measurements, which is the reason for drawing a best-fit line.','Forgetting the factor of 2. The slope of h against t² is g/2, not g.']}
  ],
  lab:{set:{exp:'drop',tx:'none',ty:'sq',noise:1},act:'all',look:'This is the ball drop, with t² on the vertical axis and h on the horizontal axis, so here the slope is 2/g. Read <b>Is it a straight line?</b>, then, at Closer look, <b>Slope</b> and <b>Constant from the slope</b>. Try other axis choices to see which ones curve.'}}],

/* ===================== Unit 2: Force and translational dynamics ===================== */
forces:[{id:'forces-1',kind:'ap',type:'Translation between representations',title:'Pushing a crate across the floor',minutes:27,
  stem:`<p>A student pushes a 40 kg crate across a level wooden floor with a constant horizontal force of 200 N. The crate starts from rest and begins to slide. The coefficient of static friction between the crate and the floor is 0.40, and the coefficient of kinetic friction is 0.30. Use g = 9.8 m/s².</p>${figCrate}`,
  parts:[
  {label:'a',kind:'sketch',pts:3,q:'Draw a free-body diagram of the crate while it slides. Represent the crate as a dot, and draw each force as an arrow that starts on the dot and points in the direction of the force. Label each force with a descriptive name or a symbol.',
    guide:['For a downward gravitational force (weight) and an upward normal force, both labeled','For a horizontal applied force in the direction of the push and a kinetic friction force in the opposite direction, both labeled','For no extra forces, such as a “net force,” “force of motion” or “force from the crate on the student” arrow'],
    model:'<p>Four arrows from the dot: weight F<sub>g</sub> = mg pointing down; the normal force F<sub>N</sub> pointing up, the same length as the weight; the push F<sub>P</sub> = 200 N pointing right; and kinetic friction f<sub>k</sub> pointing left, shorter than the push. Nothing else.</p>',
    mistakes:['Adding a “net force” or “force of motion” arrow. The net force is the sum of the arrows you drew. It is not another force.','Drawing the force the crate exerts on the student. That force acts on the student, so it does not belong on the crate’s diagram.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the acceleration a of the crate in terms of the push F, the mass m, the coefficient of kinetic friction μ<sub>k</sub>, and physical constants as appropriate. Begin with Newton’s second law.',
    guide:['For applying Newton’s second law to the horizontal forces, consistent with your diagram: F − f<sub>k</sub> = ma','For using f<sub>k</sub> = μ<sub>k</sub>F<sub>N</sub> with F<sub>N</sub> = mg, from the vertical forces balancing','For a = (F − μ<sub>k</sub>mg)/m, or a = F/m − μ<sub>k</sub>g'],
    model:'<p>Vertical: the crate does not move up or down, so F<sub>N</sub> − mg = 0 and F<sub>N</sub> = mg. Kinetic friction: f<sub>k</sub> = μ<sub>k</sub>F<sub>N</sub> = μ<sub>k</sub>mg.</p><p>Horizontal, taking the push direction as positive: ΣF<sub>x</sub> = ma, so F − μ<sub>k</sub>mg = ma and <b>a = (F − μ<sub>k</sub>mg)/m</b>.</p>',
    mistakes:['Using μ<sub>s</sub> for a crate that is already sliding. Static friction applies only while the surfaces are not slipping.','Sign error: adding friction to the push (F + f<sub>k</sub>). Friction opposes the sliding, so it points against the push.']},
  {label:'c',kind:'calc',pts:2,q:'Calculate the acceleration of the crate.',num:{ans:2.06,tol:0.05,unit:'m/s²'},
    guide:['For substituting F = 200 N, m = 40 kg and μ<sub>k</sub> = 0.30 into an expression consistent with part (b)','For a ≈ 2.1 m/s² (2.06 m/s²), with units'],
    model:'<p>f<sub>k</sub> = 0.30 × 40 × 9.8 = 117.6 N. a = (200 − 117.6) ÷ 40 = 82.4 ÷ 40 = <b>2.06 m/s²</b>.</p>',
    mistakes:['Writing a = F/m = 5.0 m/s². That leaves out friction. Use the net force.']},
  {label:'d',kind:'explain',pts:2,q:'The student says, “By Newton’s third law, the crate pushes back on me with 200 N. Those two forces balance, so the crate should not speed up. Since it does speed up, my push on the crate must be bigger than the crate’s push on me.” Explain what is wrong with the student’s reasoning.',
    guide:['For stating that the push and the push back are equal in size (200 N each), even while the crate speeds up','For explaining that the two forces act on different objects, so they cannot balance or cancel, and the crate’s acceleration depends only on the forces exerted on the crate (the push and friction)'],
    model:'<p>The two forces are a third-law pair, so they are always equal in size: 200 N each, even while the crate speeds up. But they act on different objects. The student’s push acts on the crate. The crate’s push acts on the student. Forces only add up, or balance, when they act on the same object. The crate speeds up because the forces on the crate, 200 N forward and 117.6 N of friction backward, add to a net force of 82.4 N.</p>',
    mistakes:['Agreeing that “the forces balance.” A third-law pair never balances, because the two forces act on different objects.','Saying the push must be bigger than the push back. Third-law forces are equal in size at every instant, whether or not anything accelerates.']},
  {label:'e',kind:'sketch',pts:2,q:'The student pushes for 3.0 s and then lets go, and the crate slides to a stop. Sketch the crate’s velocity as a function of time from t = 0 until it stops. Label the velocity at t = 3.0 s and the time it stops.',
    guide:['For a straight line with a positive slope from 0 to 3.0 s, reaching about 6.2 m/s','For a straight line with a steeper negative slope after 3.0 s (a slope of about −2.9 m/s²) that reaches zero at about 5.1 s and stays at zero'],
    model:'<p>From 0 to 3.0 s: a straight line up to v = 2.06 × 3.0 = 6.18 m/s. After the student lets go, only friction acts horizontally, so a = −μ<sub>k</sub>g = −2.94 m/s². The line slopes down more steeply and reaches zero at 3.0 + 6.18 ÷ 2.94 = 5.1 s. Then it stays at zero, because friction cannot push the crate backward.</p>',
    mistakes:['Continuing the line below zero. Kinetic friction stops the crate. It does not start it moving the other way.','Making the slowing-down slope the same as the speeding-up slope. Speeding up, the net force is 82.4 N. Slowing down, it is 117.6 N, so the second slope is steeper.']}
  ],
  lab:{set:{mode:'push',applied:200,mass:40,surface:'wood',strobe:true},look:'A 200 N push on a 40 kg crate on wood. Read <b>Friction on the crate</b>, <b>Net force</b> and <b>Acceleration</b>. At Closer look, compare your push with <b>Crate pushes back on you</b>.'},
  verify:[{set:{mode:'push',applied:200,mass:40,surface:'wood'},run:1,m:'acc',v:2.06,tol:0.01},{set:{mode:'push',applied:200,mass:40,surface:'wood'},run:1,m:'fric',v:-117.6,tol:0.5},{set:{mode:'push',applied:200,mass:40,surface:'wood'},run:1,m:'react',v:-200,tol:0.5}]}],

friction:[{id:'friction-1',kind:'ap',type:'Experimental design and analysis',title:'How rough is felt?',minutes:25,
  stem:`<p>A student wants to find the coefficient of kinetic friction μ<sub>k</sub> between a wooden block and a felt-covered table. She has the 0.50 kg block, a set of slotted masses that can be stacked on the block, a spring scale, a string and an electronic balance.</p>${figScale}`,
  parts:[
  {label:'a',kind:'explain',pts:3,q:'Describe a procedure she could use to collect data for finding μ<sub>k</sub>. Include what she measures and how she measures it, and one way to reduce experimental uncertainty.',
    guide:['For pulling the block with the spring scale held horizontally at a constant speed, and recording the scale reading as the kinetic friction force','For measuring the total mass on the balance for each trial (block plus added masses), finding the normal force as mg, and repeating with several different added masses','For a way to reduce uncertainty, for example repeating each pull and averaging the readings'],
    model:'<p>Measure the mass of the block on the balance. Tie the string to the block and pull it across the felt with the spring scale held level, at a slow, steady speed. Once it is sliding steadily, read the scale. Since the speed is constant, the net force is zero, so the scale reading equals the kinetic friction force. The normal force equals the weight, mg, because the table is level and the pull is horizontal. Stack masses on the block to change the normal force, and repeat for five total masses. Do three pulls for each mass and average the readings.</p>',
    mistakes:['Reading the biggest force, just as the block starts to move. That peak is static friction. For μ<sub>k</sub>, read the scale while the block slides at constant speed.','Pulling at an angle. An upward tilt lifts part of the block’s weight, so the normal force is no longer mg.']},
  {label:'b',kind:'explain',pts:2,q:'Identify the quantities she should graph to get a straight line whose slope is μ<sub>k</sub>, and explain why the slope equals μ<sub>k</sub>.',
    guide:['For graphing the friction force (the scale reading) on the vertical axis against the normal force on the horizontal axis','For explaining that f<sub>k</sub> = μ<sub>k</sub>F<sub>N</sub>, so the slope of f<sub>k</sub> against F<sub>N</sub> is μ<sub>k</sub>'],
    model:'<p>Graph the friction force f<sub>k</sub> (the scale reading) on the vertical axis and the normal force F<sub>N</sub> = mg on the horizontal axis. Since f<sub>k</sub> = μ<sub>k</sub>F<sub>N</sub>, the graph is a straight line through the origin with <b>slope = μ<sub>k</sub></b>.</p>',
    mistakes:['Wrong axes: graphing friction against mass and calling the slope μ<sub>k</sub>. The slope of f<sub>k</sub> against m is μ<sub>k</sub>g, about 2.5 N/kg here. Either divide by g or put the normal force on the horizontal axis.','Putting the normal force on the vertical axis. That graph is a straight line too, but its slope is 1/μ<sub>k</sub>, so you have to say so.']},
  {label:'c',kind:'sketch',pts:3,q:`<p>Her averaged results are below.</p>${tbl('Spring scale readings while the block slides at constant speed',['Trial','Total mass on the table (kg)','Scale reading (N)'],[['1','0.50','1.25'],['2','0.75','1.80'],['3','1.00','2.50'],['4','1.25','3.05'],['5','1.50','3.70']])}<p>Plot the data as you described in part (b). Label the axes with quantities and units, use a linear scale, and draw a best-fit line.</p>`,
    guide:['For labeling both axes with quantities and units, on linear scales, consistent with part (b)','For plotting the data points correctly (normal forces from 4.9 N to 14.7 N)','For drawing a single straight best-fit line that follows the trend of the points'],
    model:'<p>Normal forces: 4.90, 7.35, 9.80, 12.25 and 14.70 N. With friction force (N) on the vertical axis from 0 to 4 N, and normal force (N) on the horizontal axis from 0 to 15 N, the points lie close to a straight line that passes through the origin and near (14 N, 3.5 N).</p>',
    mistakes:['Plotting mass on the horizontal axis after choosing normal force in part (b). Your graph must match the quantities you named.','Forcing the line through every point, or connecting the dots. Draw one straight line with about as many points above it as below.']},
  {label:'d',kind:'calc',pts:2,q:'Use your best-fit line to calculate μ<sub>k</sub>.',num:{ans:0.25,tol:0.02,unit:''},
    guide:['For calculating the slope from two points on the best-fit line and identifying the slope as μ<sub>k</sub> (or relating it correctly, if you chose different axes)','For μ<sub>k</sub> between 0.23 and 0.27, with no units'],
    model:'<p>Points on the line: (0, 0) and (14 N, 3.5 N). Slope = 3.5 N ÷ 14 N = 0.25, so <b>μ<sub>k</sub> = 0.25</b>. It has no units, since it is a force divided by a force.</p>',
    mistakes:['Giving μ<sub>k</sub> a unit such as N or N/kg. A slope in N/kg means mass is on the horizontal axis: divide by g = 9.8 N/kg.']}
  ],
  lab:{set:{method:'pull',surface:'felt',added:0},act:'again',look:'The 0.50 kg block on felt. Read <b>Force to keep it moving</b> and <b>Normal force</b>. Raise <b>Mass added on top</b> by 0.25 kg, press <b>Pull again</b>, and watch both change. At Deep dive, read <b>Slope of friction vs. N</b>.'},
  verify:[{set:{method:'pull',surface:'felt',added:0},m:'normal',v:4.90,tol:0.01},{set:{method:'pull',surface:'felt',added:1.0},m:'normal',v:14.70,tol:0.01},{set:{method:'pull',surface:'felt',added:0.5},act:'again',run:8,m:'kin',v:2.45,tol:0.12}]}],

incline:[{id:'incline-1',kind:'ap',type:'Translation between representations',title:'A block sliding down a ramp',minutes:27,
  stem:`<p>A 5.0 kg block is released from rest on a wooden ramp tilted at θ = 30° above the horizontal. The coefficient of static friction between the block and the ramp is 0.45, and the coefficient of kinetic friction is 0.30. The block slides down the ramp. Use g = 9.8 m/s².</p>${figRamp}`,
  parts:[
  {label:'a',kind:'sketch',pts:3,q:'Draw a free-body diagram of the block while it slides down the ramp. Represent the block as a dot. Draw each force as an arrow that starts on the dot, and label each force.',
    guide:['For a gravitational force pointing straight down (not perpendicular to the ramp), labeled','For a normal force perpendicular to the ramp surface and a friction force parallel to the ramp pointing up the slope, both labeled','For no extra forces, such as a separate “force down the ramp” or a “net force” arrow drawn as another force'],
    model:'<p>Three forces: weight mg straight down; the normal force F<sub>N</sub> perpendicular to the ramp, pointing away from the surface; and kinetic friction f<sub>k</sub> along the ramp, pointing up the slope, opposite the sliding. If you show the components mg sin θ and mg cos θ, draw them dashed and label them as parts of the weight, not as new forces.</p>',
    mistakes:['Drawing mg sin θ and mg cos θ as solid arrows next to the weight. That counts gravity twice, and readers treat the extra arrows as extra forces.','Drawing the normal force straight up. It is perpendicular to the surface it comes from, the tilted ramp.','Pointing friction down the ramp. Friction opposes the block’s sliding, so it points up the slope.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the magnitude of the block’s acceleration in terms of θ, μ<sub>k</sub>, and physical constants as appropriate. Begin with Newton’s second law.',
    guide:['For applying Newton’s second law along the ramp, consistent with your diagram: mg sin θ − f<sub>k</sub> = ma','For F<sub>N</sub> = mg cos θ from the perpendicular forces balancing, so f<sub>k</sub> = μ<sub>k</sub>mg cos θ','For a = g(sin θ − μ<sub>k</sub> cos θ)'],
    model:'<p>Use axes along and perpendicular to the ramp, with down the ramp positive. Perpendicular: there is no acceleration, so F<sub>N</sub> = mg cos θ and f<sub>k</sub> = μ<sub>k</sub>mg cos θ.</p><p>Along the ramp: mg sin θ − μ<sub>k</sub>mg cos θ = ma. The mass cancels: <b>a = g(sin θ − μ<sub>k</sub> cos θ)</b>.</p>',
    mistakes:['Using F<sub>N</sub> = mg. On a ramp the normal force is smaller than the weight: mg cos θ.','Mixing up sine and cosine. Check with an extreme case: on a level surface (θ = 0) gravity should not pull the block along it, and sin 0 = 0.']},
  {label:'c',kind:'calc',pts:2,q:'Calculate the block’s acceleration.',num:{ans:2.35,tol:0.05,unit:'m/s²'},
    guide:['For substituting θ = 30° and μ<sub>k</sub> = 0.30 into an expression consistent with part (b)','For a ≈ 2.4 m/s² (2.35 m/s²), with units'],
    model:'<p>a = 9.8 × (sin 30° − 0.30 × cos 30°) = 9.8 × (0.500 − 0.260) = <b>2.35 m/s²</b>, down the ramp.</p>',
    mistakes:['Leaving the calculator in radian mode. In radians, sin 30 is −0.99, which gives a negative answer. Switch to degrees.']},
  {label:'d',kind:'sketch',pts:2,q:'The same block is placed at rest on the same ramp set to different angles, from 0° to 60°. On a set of axes, sketch the block’s acceleration as a function of the ramp angle θ. Label the angle at which the block first starts to slide.',
    guide:['For a = 0 from 0° up to about 24°, the angle where tan θ = μ<sub>s</sub> = 0.45 and the block first slides','For a curve above that angle that starts at about 1.3 m/s² and increases (to about 7.0 m/s² at 60°), consistent with part (b)'],
    model:'<p>Below the angle where it first slips, static friction holds the block still, so a = 0. It slips when mg sin θ is bigger than the most static friction can supply, μ<sub>s</sub>mg cos θ. That happens when tan θ is greater than 0.45, at θ = 24.2°. Above that, a = g(sin θ − 0.30 cos θ). It jumps to about 1.34 m/s² right at 24.2°, because kinetic friction is less than the maximum static friction, then rises to 2.35 m/s² at 30° and 7.0 m/s² at 60°.</p>',
    mistakes:['Starting the curve at θ = 0. A block at rest on a gentle slope does not slide, because static friction can hold it.','Using μ<sub>k</sub> to find where it starts to slide. Whether it starts to slide depends on μ<sub>s</sub>.']},
  {label:'e',kind:'explain',pts:2,q:'A 10 kg block made of the same wood is released on the same 30° ramp. Is its acceleration greater than, less than, or equal to the acceleration of the 5.0 kg block? Justify your answer using your expression from part (b).',
    guide:['For stating that the acceleration is the same (equal)','For a justification that refers to part (b): the mass cancels, because both the pull of gravity along the ramp and the friction force are proportional to m, so a does not depend on m'],
    model:'<p>Equal. Doubling the mass doubles mg sin θ, the part of gravity pulling the block down the ramp. It also doubles the normal force, and so doubles the friction. The net force doubles, but so does the mass it has to accelerate. In a = g(sin θ − μ<sub>k</sub> cos θ) there is no m at all.</p>',
    mistakes:['Saying the heavier block speeds up faster because more weight pulls it down. The heavier block also has more friction and more inertia.']}
  ],
  lab:{set:{angle:30,mass:5,surface:'wood',push:0,phi:0,strobe:true},act:'again',look:'A 5.0 kg block on a 30° wooden ramp. Read <b>Acceleration down the ramp</b>, <b>Normal force</b> and <b>Friction</b>. Then try 10 kg, and try angles below and above 24°.'},
  verify:[{set:{angle:30,mass:5,surface:'wood'},act:'again',run:0.5,m:'acc',v:2.35,tol:0.01},{set:{angle:30,mass:10,surface:'wood'},act:'again',run:0.5,m:'acc',v:2.35,tol:0.01},{set:{angle:30,mass:5,surface:'wood'},m:'normal',v:42.4,tol:0.1},{set:{angle:30,mass:5,surface:'wood'},m:'repose',v:24.2,tol:0.1},{set:{angle:60,mass:5,surface:'wood'},act:'again',run:0.3,m:'acc',v:7.02,tol:0.02},{set:{angle:20,mass:5,surface:'wood'},act:'again',run:1,m:'acc',v:0,tol:0.001}]}],

atwood:[
 {id:'atwood-1',kind:'ap',type:'Mathematical routines',title:'A block pulled by a hanging mass',minutes:22,
  stem:`<p>Block 1, of mass m<sub>1</sub> = 2.0 kg, sits on a level table. A light string tied to it runs over a light, frictionless pulley at the table’s edge to Block 2, of mass m<sub>2</sub> = 1.0 kg, which hangs freely. The coefficient of kinetic friction between Block 1 and the table is 0.20. The blocks are released from rest, and Block 2 moves down. Use g = 9.8 m/s².</p>${figTable}`,
  parts:[
  {label:'a',kind:'sketch',pts:2,q:'Draw free-body diagrams for Block 1 and for Block 2. Represent each block as a dot, and draw each force as a labeled arrow that starts on the dot.',
    guide:['For Block 1: weight down, normal force up, tension toward the pulley, and kinetic friction away from the pulley, all labeled','For Block 2: tension up and weight down, labeled, with no extra forces on either diagram (for example, Block 2’s weight drawn on Block 1, or a separate “pulley force”)'],
    model:'<p>Block 1: m<sub>1</sub>g down and F<sub>N</sub> up (the same length), tension T toward the pulley, and friction f<sub>k</sub> away from the pulley (shorter than T). Block 2: T up and m<sub>2</sub>g down, with the weight arrow longer, since Block 2 speeds up downward.</p>',
    mistakes:['Drawing Block 2’s weight as a force on Block 1. Block 2’s weight acts on Block 2. What reaches Block 1 is the string’s tension.','Drawing the tension on Block 2 the same length as its weight. If they were equal, Block 2 could not speed up.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the acceleration a of the blocks in terms of m<sub>1</sub>, m<sub>2</sub>, μ<sub>k</sub>, and physical constants as appropriate. Begin your derivation by writing Newton’s second law for each block or for the two-block system.',
    guide:['For applying Newton’s second law with consistent directions, either to each block (m<sub>2</sub>g − T = m<sub>2</sub>a and T − f<sub>k</sub> = m<sub>1</sub>a) or to the two-block system (m<sub>2</sub>g − f<sub>k</sub> = (m<sub>1</sub> + m<sub>2</sub>)a)','For substituting f<sub>k</sub> = μ<sub>k</sub>m<sub>1</sub>g, using F<sub>N</sub> = m<sub>1</sub>g for Block 1 only','For a = (m<sub>2</sub> − μ<sub>k</sub>m<sub>1</sub>)g/(m<sub>1</sub> + m<sub>2</sub>)'],
    model:'<p>Block 2, with down positive: m<sub>2</sub>g − T = m<sub>2</sub>a. Block 1, with toward the pulley positive: T − f<sub>k</sub> = m<sub>1</sub>a. Block 1 does not move vertically, so F<sub>N</sub> = m<sub>1</sub>g and f<sub>k</sub> = μ<sub>k</sub>m<sub>1</sub>g.</p><p>Adding the two equations cancels T: m<sub>2</sub>g − μ<sub>k</sub>m<sub>1</sub>g = (m<sub>1</sub> + m<sub>2</sub>)a, so <b>a = (m<sub>2</sub> − μ<sub>k</sub>m<sub>1</sub>)g/(m<sub>1</sub> + m<sub>2</sub>)</b>.</p>',
    mistakes:['Using μ<sub>k</sub>(m<sub>1</sub> + m<sub>2</sub>)g for friction. Only Block 1 touches the table.','Dividing by only one block’s mass. The net force has to accelerate both blocks.']},
  {label:'c',kind:'calc',pts:1,q:'Calculate the acceleration of the blocks.',num:{ans:1.96,tol:0.05,unit:'m/s²'},
    guide:['For a ≈ 2.0 m/s² (1.96 m/s²), with substitution into an expression consistent with part (b)'],
    model:'<p>a = (1.0 − 0.20 × 2.0) × 9.8 ÷ (2.0 + 1.0) = 0.60 × 9.8 ÷ 3.0 = <b>1.96 m/s²</b>. Friction on Block 1 is 0.20 × 2.0 × 9.8 = 3.92 N.</p>',
    mistakes:['Substituting μ<sub>k</sub> times the wrong mass. The friction term uses m<sub>1</sub>, the block on the table.']},
  {label:'d',kind:'calc',pts:1,q:'Calculate the tension in the string.',num:{ans:7.84,tol:0.1,unit:'N'},
    guide:['For T ≈ 7.8 N (7.84 N), from Newton’s second law applied to one block, for example T = m<sub>2</sub>(g − a)'],
    model:'<p>For Block 2, with down positive: m<sub>2</sub>g − T = m<sub>2</sub>a, so T = 1.0 × (9.8 − 1.96) = <b>7.84 N</b>. Check with Block 1: T − f<sub>k</sub> = 7.84 − 3.92 = 3.92 N, which equals 2.0 kg × 1.96 m/s².</p>',
    mistakes:['Setting T equal to Block 2’s weight, 9.8 N. Then Block 2 would have no net force and could not accelerate.']},
  {label:'e',kind:'explain',pts:3,q:'The table is replaced with one that has negligible friction. A student says, “Now nothing holds the blocks back, so Block 2 falls with acceleration g.” Do you agree or disagree? Justify your answer.',
    guide:['For disagreeing: the acceleration is less than g (setting μ<sub>k</sub> = 0 in part (b) gives m<sub>2</sub>g/(m<sub>1</sub> + m<sub>2</sub>) = 3.3 m/s²)','For justifying that the only unbalanced force, Block 2’s weight, has to accelerate the mass of both blocks','For justifying that the string still pulls up on Block 2 with a nonzero tension, so the net force on Block 2 is less than its weight'],
    model:'<p>Disagree. With μ<sub>k</sub> = 0, the expression from part (b) becomes a = m<sub>2</sub>g/(m<sub>1</sub> + m<sub>2</sub>) = 9.8 N ÷ 3.0 kg = 3.3 m/s², less than g. The only unbalanced force on the system is Block 2’s weight, and it has to speed up 3.0 kg of blocks, not just 1.0 kg. Looked at from Block 2 alone, the string still pulls up on it, because the string has to drag Block 1 along (T = m<sub>1</sub>a = 6.5 N). With an upward force on it, Block 2’s net force is less than its weight, so its acceleration is less than g.</p>',
    mistakes:['Agreeing because friction was the only thing slowing it down. Block 1’s inertia also resists, through the string.','Claiming the tension becomes zero without friction. The string still has to accelerate Block 1.']}
  ],
  lab:{set:{mode:'table',m1:2.0,m2:1.0,mu:0.2,Mp:0},look:'Block 1 is 2.0 kg on the table with μ = 0.20, and 1.0 kg hangs. Read <b>Acceleration</b> and, at Closer look, <b>Tension pulling m₁</b> and <b>Friction on m₁</b>. Then set <b>Table friction μ</b> to 0 and compare.'},
  verify:[{set:{mode:'table',m1:2.0,m2:1.0,mu:0.2,Mp:0},m:'pred',v:1.96,tol:0.005},{set:{mode:'table',m1:2.0,m2:1.0,mu:0.2,Mp:0},runPhase:true,m:'T1',v:7.84,tol:0.01},{set:{mode:'table',m1:2.0,m2:1.0,mu:0.2,Mp:0},runPhase:true,m:'fric',v:3.92,tol:0.01},{set:{mode:'table',m1:2.0,m2:1.0,mu:0,Mp:0},m:'pred',v:3.27,tol:0.01},{set:{mode:'table',m1:2.0,m2:1.0,mu:0.2,Mp:0},runPhase:true,m:'acc',v:1.96,tol:0.01}]},
 {id:'atwood-2',kind:'ap',type:'Experimental design and analysis',title:'Finding g with an Atwood machine',minutes:25,
  stem:`<p>Two masses hang from a string that passes over a pulley. A group keeps the total mass at m<sub>1</sub> + m<sub>2</sub> = 2.0 kg and moves slotted masses from one side to the other to change the difference m<sub>2</sub> − m<sub>1</sub>. Each time, they release the system from rest and time how long the heavier side takes to fall a measured distance. They want to use their data to find g.</p>${figAtwood}`,
  parts:[
  {label:'a',kind:'explain',pts:2,q:'Describe how they can find the acceleration of the system from their measurements, and give one way to reduce experimental uncertainty in that acceleration.',
    guide:['For measuring the distance fallen d (with a meterstick) and the time t (with a stopwatch or photogate) from rest, and using a = 2d/t², from d = ½at²','For a way to reduce uncertainty, for example repeating each run and averaging the times, or using a longer fall distance so the time is large compared with reaction time'],
    model:'<p>Measure the distance d the heavier mass falls with a meterstick, and time the fall from release with a photogate or stopwatch. The system starts from rest with constant acceleration, so d = ½at² and a = 2d/t². Do several runs at each setting and average the times. A longer drop, like 0.80 m instead of 0.20 m, also helps, because a reaction-time error of 0.1 s is a smaller fraction of a longer time.</p>',
    mistakes:['Using a = d/t or a = 2d/t. Those are speeds, not accelerations. From rest, d = ½at², so a = 2d/t².']},
  {label:'b',kind:'explain',pts:3,q:'Assume the string and pulley have negligible mass and friction. Using Newton’s second law, show which quantities they should graph to get a straight line whose slope is g. State what goes on each axis.',
    guide:['For applying Newton’s second law to the two-mass system: the net force (m<sub>2</sub> − m<sub>1</sub>)g accelerates the total mass, so (m<sub>2</sub> − m<sub>1</sub>)g = (m<sub>1</sub> + m<sub>2</sub>)a','For rearranging to a = g × (m<sub>2</sub> − m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>)','For graphing a on the vertical axis against (m<sub>2</sub> − m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>) on the horizontal axis, with a slope equal to g (or against m<sub>2</sub> − m<sub>1</sub>, with a slope of g ÷ 2.0 kg)'],
    model:'<p>Treat both masses as one system moving in the direction the heavier side falls. The outside forces along that direction are m<sub>2</sub>g one way and m<sub>1</sub>g the other, so (m<sub>2</sub> − m<sub>1</sub>)g = (m<sub>1</sub> + m<sub>2</sub>)a, and a = g × (m<sub>2</sub> − m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>). Graph a on the vertical axis and the ratio (m<sub>2</sub> − m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>) on the horizontal axis. That is a straight line through the origin with <b>slope = g</b>.</p>',
    mistakes:['Graphing a against m<sub>2</sub> − m<sub>1</sub> and calling the slope g. With a fixed total of 2.0 kg, that slope is g ÷ 2.0 kg, so multiply it by 2.0 kg.','Wrong axes: graphing a against m<sub>2</sub>/m<sub>1</sub>. That ratio is not what appears in the equation for a, so the points curve.']},
  {label:'c',kind:'sketch',pts:3,q:`<p>The group’s results are below. Each acceleration is an average of three runs.</p>${tbl('Atwood machine results (total mass 2.0 kg)',['m<sub>1</sub> (kg)','m<sub>2</sub> (kg)','Acceleration a (m/s²)'],[['0.90','1.10','0.95'],['0.80','1.20','1.85'],['0.70','1.30','2.82'],['0.60','1.40','3.71'],['0.50','1.50','4.68']])}<p>Plot the data as you described in part (b). Label the axes with quantities and units, use a linear scale, and draw a best-fit line.</p>`,
    guide:['For labeling both axes with quantities and units (the mass ratio has no units), on linear scales','For plotting the data points correctly','For drawing a single straight best-fit line that follows the trend of the points'],
    model:'<p>Ratios (m<sub>2</sub> − m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>): 0.10, 0.20, 0.30, 0.40 and 0.50, with no units. With a (m/s²) on the vertical axis from 0 to 5 and the ratio on the horizontal axis from 0 to 0.5, the points lie close to a straight line through the origin and near (0.50, 4.67 m/s²).</p>',
    mistakes:['Giving the ratio a unit such as kg. It is kilograms divided by kilograms, so it has none.','Connecting the dots instead of drawing one best-fit line.']},
  {label:'d',kind:'calc',pts:1,q:'Use your best-fit line to calculate g.',num:{ans:9.3,tol:0.3,unit:'m/s²'},
    guide:['For a slope taken from two points on the best-fit line, giving g between 9.0 and 9.6 m/s²'],
    model:'<p>Points on the line: (0, 0) and (0.50, 4.67 m/s²). Slope = 4.67 ÷ 0.50 = <b>9.3 m/s²</b>.</p>',
    mistakes:['Using a single row, for example 4.68 ÷ 0.50. A best-fit line uses all five measurements.']},
  {label:'e',kind:'explain',pts:1,q:'The value from part (d) is less than 9.8 m/s². Give one physical reason this experiment gives a value below 9.8 m/s², other than human error in timing.',
    guide:['For a physical reason that makes the measured acceleration smaller, for example: the pulley has mass, so part of the net force goes into making it rotate; or friction in the pulley’s axle, or air resistance, acts against the motion'],
    model:'<p>The pulley is not massless. Part of the net force goes into spinning the pulley up, so the masses speed up a little less than the equation predicts. A uniform 0.20 kg pulley acts like an extra 0.10 kg of mass to accelerate: a = g(m<sub>2</sub> − m<sub>1</sub>) ÷ 2.10 kg. That makes the slope 9.8 × 2.0 ÷ 2.1 = 9.3 m/s², which matches the data.</p>',
    mistakes:['Writing “human error” or “measurement error.” Readers want a physical cause that pushes the result in a specific direction.']}
  ],
  lab:{set:{mode:'atwood',m1:0.9,m2:1.1,Mp:0.2},look:'The first row of the table, with a 0.20 kg pulley. Read <b>Acceleration</b> and <b>Timer: a = 2d/t²</b>. Move 0.1 kg from m₁ to m₂ for each new row. At Deep dive, set <b>Pulley mass M</b> to 0 and see what the slope would be.'},
  verify:[{set:{mode:'atwood',m1:0.9,m2:1.1,Mp:0.2},m:'pred',v:0.933,tol:0.005},{set:{mode:'atwood',m1:0.7,m2:1.3,Mp:0.2},m:'pred',v:2.80,tol:0.005},{set:{mode:'atwood',m1:0.5,m2:1.5,Mp:0.2},m:'pred',v:4.667,tol:0.005},{set:{mode:'atwood',m1:0.5,m2:1.5,Mp:0},m:'pred',v:4.90,tol:0.005}]}
],

circular:[{id:'circular-1',kind:'ap',type:'Mathematical routines',title:'A car on a flat curve',minutes:22,
  stem:`<p>A 1200 kg car drives around a flat, unbanked curve of radius 50 m at constant speed. The coefficient of static friction between the tires and the dry road is 0.70. Use g = 9.8 m/s².</p>${figCurve}`,
  parts:[
  {label:'a',kind:'sketch',pts:2,q:'Draw a free-body diagram of the car as seen from behind, with the center of the curve to the left. Represent the car as a dot, and draw each force as a labeled arrow that starts on the dot.',
    guide:['For a weight force down, a normal force up, and a static friction force pointing horizontally toward the center of the curve (to the left), all labeled','For no extra forces, such as a separate “centripetal force” arrow or an outward “centrifugal force” arrow'],
    model:'<p>Three forces: weight mg down; the normal force F<sub>N</sub> up, the same length; and static friction f<sub>s</sub> pointing left, toward the center of the curve. Friction is the centripetal force here, so there is no separate centripetal arrow.</p>',
    mistakes:['Drawing a “centripetal force” arrow as an extra force. Centripetal describes a job a force does, not a new force. Here, friction does that job.','Drawing an outward “centrifugal force.” Nothing pushes the car outward. The car tends to keep going straight, and friction turns it.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the greatest speed v<sub>max</sub> at which the car can take the curve without sliding, in terms of μ<sub>s</sub>, r, and physical constants as appropriate. Begin with Newton’s second law.',
    guide:['For applying Newton’s second law toward the center: the friction force equals mv²/r','For using the maximum static friction, f<sub>s,max</sub> = μ<sub>s</sub>F<sub>N</sub>, with F<sub>N</sub> = mg','For v<sub>max</sub> = √(μ<sub>s</sub>gr)'],
    model:'<p>Toward the center, ΣF = ma<sub>c</sub>: f<sub>s</sub> = mv²/r. Vertically, F<sub>N</sub> = mg. The car goes fastest when friction is at its largest, f<sub>s</sub> = μ<sub>s</sub>mg, so μ<sub>s</sub>mg = mv<sub>max</sub>²/r and <b>v<sub>max</sub> = √(μ<sub>s</sub>gr)</b>.</p>',
    mistakes:['Setting the net force to zero because the speed is constant. The direction of the velocity is changing, so the car is accelerating toward the center.','Using kinetic friction. The tires roll without slipping, so the friction is static.']},
  {label:'c',kind:'calc',pts:2,q:'Calculate v<sub>max</sub>.',num:{ans:18.5,tol:0.2,unit:'m/s'},
    guide:['For substituting μ<sub>s</sub> = 0.70 and r = 50 m into an expression consistent with part (b)','For v<sub>max</sub> ≈ 19 m/s (18.5 m/s)'],
    model:'<p>v<sub>max</sub> = √(0.70 × 9.8 × 50) = √343 = <b>18.5 m/s</b>, about 67 km/h.</p>',
    mistakes:['Forgetting the square root and answering 343 m/s.']},
  {label:'d',kind:'explain',pts:2,q:'A loaded truck with twice the car’s mass takes the same curve on the same road. A student says the truck’s greatest safe speed is lower because it is heavier. Do you agree or disagree? Justify your answer.',
    guide:['For disagreeing: the greatest safe speed is the same (18.5 m/s)','For justifying that the friction needed (mv²/r) and the friction available (μ<sub>s</sub>mg) are both proportional to mass, so mass cancels, as in v<sub>max</sub> = √(μ<sub>s</sub>gr)'],
    model:'<p>Disagree. Twice the mass needs twice the friction to turn at a given speed, because mv²/r doubles. But twice the mass also presses down twice as hard, so the maximum friction μ<sub>s</sub>mg doubles too. The mass cancels, and v<sub>max</sub> = √(μ<sub>s</sub>gr) has no m in it. Real trucks slow down on curves for other reasons, like the risk of tipping over.</p>',
    mistakes:['Agreeing because heavier things are harder to turn. They are, but they also get more friction, in exactly the same proportion.']},
  {label:'e',kind:'calc',pts:1,q:'The car takes the curve at 15 m/s. Calculate the friction force the road exerts on the car.',num:{ans:5400,tol:60,unit:'N'},
    guide:['For f = mv²/r = 5400 N (5.4 × 10³ N), with supporting work'],
    model:'<p>f = mv²/r = 1200 × 15² ÷ 50 = <b>5400 N</b>. That is less than the most the road can supply, 0.70 × 1200 × 9.8 = 8232 N, so the car holds the road with grip to spare.</p>',
    mistakes:['Answering μ<sub>s</sub>mg = 8232 N. That is the most static friction can be, not what it is. Static friction is only as big as it needs to be.']}
  ],
  lab:{set:{mode:'curve',cv:15,cr:50,mu:0.7,bank:0,cm:1200,fbd:true},act:'go',look:'A 1200 kg car at 15 m/s on a flat 50 m curve, with μ<sub>s</sub> = 0.70. At Closer look, read <b>Friction needed</b>, <b>Max friction μN</b> and <b>Top safe speed</b>. Then change <b>Car mass</b> and watch the top safe speed.'},
  verify:[{set:{mode:'curve',cv:15,cr:50,mu:0.7,bank:0,cm:1200},m:'vmax',v:18.52,tol:0.02},{set:{mode:'curve',cv:15,cr:50,mu:0.7,bank:0,cm:1200},m:'fneed',v:5400,tol:2},{set:{mode:'curve',cv:15,cr:50,mu:0.7,bank:0,cm:1200},m:'fmax',v:8232,tol:2},{set:{mode:'curve',cv:15,cr:50,mu:0.7,bank:0,cm:2400},m:'vmax',v:18.52,tol:0.02}]}],

gravity:[{id:'gravity-1',kind:'ap',type:'Qualitative/quantitative translation',title:'Two satellites in the same orbit',minutes:20,
  stem:`<p>Satellite A and Satellite B move in circular orbits around Earth at the same orbital radius r, measured from Earth’s center. Satellite B has twice the mass of Satellite A. Earth has mass M<sub>E</sub>. Only Earth’s gravity acts on each satellite.</p>${figOrbit}`,
  parts:[
  {label:'a',kind:'explain',pts:3,q:'Is the orbital speed of Satellite B greater than, less than, or equal to the orbital speed of Satellite A? Justify your answer without using equations.',
    guide:['For stating that the speeds are equal','For justifying that Earth’s gravitational force on B is twice as large as on A, because the gravitational force is proportional to the satellite’s mass','For justifying that B also needs twice the net force to move on the same circle at the same speed, because it has twice the inertia, so the extra force exactly makes up for the extra mass'],
    model:'<p>Equal. Earth pulls on Satellite B twice as hard, because the gravitational force is proportional to the mass of the object being pulled. But B also has twice the inertia, so it needs twice the force toward the center to follow the same circle at the same speed. The two effects cancel, and both satellites have the same acceleration toward Earth. Same radius and same acceleration means the same speed.</p>',
    mistakes:['Saying B is faster because gravity pulls it harder. Gravity does pull harder, but B is also harder to accelerate.','Saying B is slower because it is heavier. That is the same mistake from the other side: counting only the extra inertia, not the extra force.']},
  {label:'b',kind:'explain',pts:3,q:'Derive an expression for the orbital speed v of a satellite of mass m in terms of r, M<sub>E</sub>, and physical constants as appropriate. Begin with Newton’s second law.',
    guide:['For setting the gravitational force equal to the satellite’s mass times its centripetal acceleration: GM<sub>E</sub>m/r² = mv²/r','For canceling the satellite’s mass m','For v = √(GM<sub>E</sub>/r)'],
    model:'<p>Gravity is the only force, so it is the net force toward the center: GM<sub>E</sub>m/r² = mv²/r. The satellite’s mass cancels. Multiplying both sides by r gives v² = GM<sub>E</sub>/r, so <b>v = √(GM<sub>E</sub>/r)</b>.</p>',
    mistakes:['Using g = 9.8 m/s² for a satellite. Gravity is weaker at orbital distances. Use Newton’s law of gravitation with the distance from Earth’s center.','Using the height above the surface for r. Newton’s law of gravitation uses the distance between the centers.']},
  {label:'c',kind:'explain',pts:2,q:'Explain how your expression from part (b) supports your answer to part (a). Then use it to describe how the orbital speed changes if a satellite moves to an orbit with twice the radius.',
    guide:['For using functional dependence: v does not depend on the satellite’s mass, which supports the claim in part (a)','For stating that v is inversely proportional to the square root of r, so doubling r makes v smaller by a factor of 1/√2 (about 0.71 times as fast)'],
    model:'<p>The expression v = √(GM<sub>E</sub>/r) has no satellite mass in it, so two satellites at the same radius have the same speed whatever their masses, as in part (a). The speed is inversely proportional to √r, so doubling the radius makes v smaller by a factor of 1/√2: the satellite moves about 0.71 times as fast. For example, 400 km above Earth’s surface (r = 6771 km), v = 7.7 km/s. At twice that radius, v = 5.4 km/s.</p>',
    mistakes:['Saying “v depends on r” without saying how. Readers look for words like “inversely proportional to the square root of r.”','Saying v halves. Because of the square root, doubling r multiplies v by 0.71, not 0.5.']}
  ],
  lab:{set:{mode:'cannon',planet:'earth',h:400,v0:7.7},act:'fire',look:'A cannonball fired level at 7.7 km/s from 400 km up. At Closer look, compare <b>Speed</b> with <b>Circular speed at launch height</b>. Raise <b>Tower height</b> and watch the circular speed drop.'},
  verify:[{set:{mode:'cannon',planet:'earth',h:400,v0:7.7},m:'vc',v:7.67,tol:0.01}]}]
});
})();
